/**
 * Molly's floral patterns, cut down to badge size and carried in this file.
 *
 * GitHub serves README images through its own proxy, so an SVG that points at
 * a picture somewhere else comes out blank there: the pattern has to travel
 * inside the picture. Each view wears the next one along, so the badge and the
 * button on the profile keep changing.
 *
 * They come from portfolio/public/palais/florals/.
 */

export interface Floral {
  key: string;
  /** the picture itself */
  uri: string;
  /** a dark colour from the pattern, for the veil the writing sits on */
  ink: string;
  /** the rim */
  gold: string;
}

export const FLORALS: Floral[] = [
  { key: "teal", ink: "#05403c", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "pink", ink: "#7a1748", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "black-gold", ink: "#12100c", gold: "#f0d894", uri: "data:image/jpeg;base64," },
  { key: "green", ink: "#1d3d1c", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "maroon", ink: "#4a0f2c", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "purple", ink: "#2f1d5e", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "orange", ink: "#7a3405", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "yellow", ink: "#6b5406", gold: "#e8c774", uri: "data:image/jpeg;base64," },
  { key: "cream", ink: "#4a4030", gold: "#c9a44c", uri: "data:image/jpeg;base64," },
  { key: "red-toile", ink: "#5c0f16", gold: "#c9a44c", uri: "data:image/jpeg;base64," },
];

/** the one to wear now: they turn, so a profile page looks different each time */
export const floralFor = (n: number) => FLORALS[Math.abs(Math.floor(n)) % FLORALS.length];

export const floralNamed = (name: string | null) => FLORALS.find((f) => f.key === name) ?? null;
